CREATE TABLE hub_ad_builds(id TEXT PRIMARY KEY,workspace_id TEXT NOT NULL,brand_id TEXT NOT NULL REFERENCES hub_brands(id),campaign_id TEXT REFERENCES hub_campaign_plans(id),name TEXT NOT NULL,platform TEXT NOT NULL,currency TEXT,payload TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('draft','ready','archived')),version INTEGER NOT NULL DEFAULT 1,client_key TEXT NOT NULL,payload_hash TEXT NOT NULL,created_by TEXT NOT NULL,updated_by TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,UNIQUE(workspace_id,client_key));
CREATE TABLE hub_ad_build_events(id TEXT PRIMARY KEY,build_id TEXT NOT NULL REFERENCES hub_ad_builds(id),author_id TEXT NOT NULL,message TEXT NOT NULL,created_at INTEGER NOT NULL);
